def hill_climb(start: list) -> tuple:
    """Move to the best neighbor until none helps."""
    cur, cur_c = start[:], cost(start)
    while True:
        best_nb = min(neighbors(cur), key=cost)
        best_c = cost(best_nb)
        if best_c >= cur_c:
            return cur, cur_c
        cur, cur_c = best_nb, best_c

